package com.tifloacosta.nativeprototype

/** Gemini credential interface messages; never modify the stored credential. */
internal object NativeReaderGeminiStrings {
    private val keys = listOf("keySaved","noKey","create","paste","saved","saveError","save","voice","quota","sample","playing","playError","listen","stop","connected","rejected","exhausted","providerError","checkError","check","deleteQuestion","deleted","deleteError","delete","help")
    private val catalog = mapOf(
        "es" to listOf("Clave guardada","Sin clave","Crear clave","Pegar clave","Clave guardada en este dispositivo.","No se pudo guardar la clave.","Guardar","Voz: ","Generando audio; puede consumir cuota de tu cuenta.","Hola. Esta es una prueba de voz Gemini en TifloLector.","Reproduciendo muestra Gemini.","No se pudo generar o reproducir audio Gemini.","Escuchar","Detener","Conexión correcta. Gemini permite leer documentos y exportar audio.","Clave rechazada o sin permisos.","Cuota agotada.","Error del proveedor: ","No se pudo comprobar la conexión.","Comprobar","¿Eliminar la clave guardada?","Clave eliminada.","No se pudo eliminar la clave.","Eliminar","Cada usuario gestiona su clave, cuota y posibles costes. TifloAcosta no proporciona una clave compartida. La muestra genera audio real y puede consumir cuota. Elige Gemini como motor para leer documentos o exportar audio."),
        "en" to listOf("Key saved","No key","Create key","Paste key","Key saved on this device.","Could not save key.","Save","Voice: ","Generating audio; your account quota may be used.","Hello. This is a Gemini voice sample in TifloLector.","Playing Gemini sample.","Could not generate or play Gemini audio.","Listen","Stop","Connection OK. Gemini can read documents and export audio.","Key rejected or insufficient permissions.","Quota exceeded.","Provider error: ","Could not check connection.","Check","Delete the saved key?","Key deleted.","Could not delete key.","Delete","Your API key and quota belong to you. The app does not provide a shared key. Gemini sample generates real audio and may use quota. Choose Gemini as the engine to read or export documents."),
        "pt" to listOf("Chave guardada","Sem chave","Criar chave","Colar chave","Chave guardada neste dispositivo.","Não foi possível guardar a chave.","Guardar","Voz: ","A gerar áudio; pode consumir a quota da tua conta.","Olá. Esta é uma amostra de voz Gemini no TifloLector.","A reproduzir amostra Gemini.","Não foi possível gerar ou reproduzir o áudio Gemini.","Ouvir","Parar","Ligação correta. O Gemini pode ler documentos e exportar áudio.","Chave rejeitada ou sem permissões suficientes.","Quota esgotada.","Erro do fornecedor: ","Não foi possível verificar a ligação.","Verificar","Eliminar a chave guardada?","Chave eliminada.","Não foi possível eliminar a chave.","Eliminar","A tua chave API e quota são pessoais. A aplicação não fornece chave partilhada. A amostra Gemini gera áudio real e pode consumir quota. Seleciona Gemini como motor para ler ou exportar documentos."),
        "fr" to listOf("Clé enregistrée","Aucune clé","Créer une clé","Coller la clé","Clé enregistrée sur cet appareil.","Impossible d’enregistrer la clé.","Enregistrer","Voix : ","Génération audio en cours ; ton quota peut être utilisé.","Bonjour. Voici un exemple de voix Gemini dans TifloLector.","Lecture de l’extrait Gemini.","Impossible de générer ou lire l’audio Gemini.","Écouter","Arrêter","Connexion réussie. Gemini peut lire les documents et exporter l’audio.","Clé rejetée ou autorisations insuffisantes.","Quota épuisé.","Erreur du fournisseur : ","Impossible de vérifier la connexion.","Vérifier","Supprimer la clé enregistrée ?","Clé supprimée.","Impossible de supprimer la clé.","Supprimer","Ta clé API et ton quota t’appartiennent. L’application ne fournit aucune clé partagée. L’extrait Gemini produit un vrai audio et peut consommer du quota. Choisis Gemini comme moteur pour lire ou exporter des documents."),
        "it" to listOf("Chiave salvata","Nessuna chiave","Crea chiave","Incolla chiave","Chiave salvata sul dispositivo.","Impossibile salvare la chiave.","Salva","Voce: ","Generazione audio in corso; potrebbe consumare la quota dell’account.","Ciao. Questa è una prova della voce Gemini in TifloLector.","Riproduzione esempio Gemini.","Impossibile generare o riprodurre l’audio Gemini.","Ascolta","Ferma","Connessione riuscita. Gemini può leggere documenti ed esportare audio.","Chiave rifiutata o permessi insufficienti.","Quota esaurita.","Errore del fornitore: ","Impossibile verificare la connessione.","Verifica","Eliminare la chiave salvata?","Chiave eliminata.","Impossibile eliminare la chiave.","Elimina","La chiave API e la quota sono personali. L’app non fornisce una chiave condivisa. L’esempio Gemini genera audio reale e può consumare quota. Scegli Gemini come motore per leggere o esportare documenti."),
        "de" to listOf("Schlüssel gespeichert","Kein Schlüssel","Schlüssel erstellen","Schlüssel einfügen","Schlüssel auf diesem Gerät gespeichert.","Schlüssel konnte nicht gespeichert werden.","Speichern","Stimme: ","Audio wird erzeugt; dein Kontingent kann verbraucht werden.","Hallo. Dies ist eine Gemini-Stimmprobe in TifloLector.","Gemini-Stimmprobe wird abgespielt.","Gemini-Audio konnte nicht erzeugt oder abgespielt werden.","Anhören","Stopp","Verbindung erfolgreich. Gemini kann Dokumente vorlesen und Audio exportieren.","Schlüssel abgelehnt oder unzureichende Berechtigungen.","Kontingent erschöpft.","Anbieterfehler: ","Verbindung konnte nicht geprüft werden.","Prüfen","Gespeicherten Schlüssel löschen?","Schlüssel gelöscht.","Schlüssel konnte nicht gelöscht werden.","Löschen","API-Schlüssel und Kontingent gehören dir. Die App stellt keinen gemeinsamen Schlüssel bereit. Gemini-Stimmproben erzeugen echtes Audio und können Kontingent verbrauchen. Wähle Gemini als Motor zum Lesen oder Exportieren von Dokumenten.")
    )
    fun get(language: String, key: String): String {
        val index = keys.indexOf(key)
        if (index < 0) return key
        return (catalog[language] ?: catalog.getValue("es"))[index]
    }
}
